package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Role     string `json:"role"`
	DeptCode string `json:"dept_code"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching employees by department and name
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	dept := r.URL.Query().Get("dept")
	name := r.URL.Query().Get("name")
	sortCol := r.URL.Query().Get("sort")

	if dept == "" {
		http.Error(w, "dept parameter required", 400)
		return
	}

	// Build query with parameterized dept but dynamic sort
	baseQuery := "SELECT id, name, email, role, dept_code FROM employees WHERE dept_code = $1"

	if name != "" {
		// Developer note: name is also parameterized, safe
		baseQuery += " AND name ILIKE $2"
	}

	// Sort column - validated against allowlist... or so we think
	if sortCol != "" {
		// BUG: validation is case-sensitive but PostgreSQL identifiers are case-insensitive
		allowedSorts := map[string]bool{"name": true, "email": true, "role": true, "id": true}
		if allowedSorts[sortCol] {
			baseQuery += " ORDER BY " + sortCol
		} else {
			// Fallback: still appends user input for "advanced" sort expressions
			// This was meant to support "name DESC" but is actually injectable
			if len(sortCol) <= 64 && !strings.Contains(sortCol, ";") {
				baseQuery += " ORDER BY " + sortCol
			}
		}
	}

	var rows *sql.Rows
	var err error

	if name != "" {
		rows, err = db.Query(baseQuery, dept, "%"+name+"%")
	} else {
		rows, err = db.Query(baseQuery, dept)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role, &sr.DeptCode); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthHandler for LB health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	fmt.Fprint(w, "ok")
}

func main() {
	http.HandleFunc("/api/v2/employees/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
